12	func newStore() (*Memory, *clock.Fake) {
13		clk := clock.NewFake(time.Date(2026, 5, 1, 0, 0, 0, 0, time.UTC))
14		return NewMemory(clk, 24*time.Hour), clk
15	}
16	
17	func TestBeginCompleteReplay(t *testing.T) {
18		ctx := context.Background()
19		s, _ := newStore()
20		_, started, err := s.Begin(ctx, "k1", "fp")
21		if err != nil || !started {
22			t.Fatalf("first Begin: started=%v err=%v", started, err)
23		}
24		if err := s.Complete(ctx, "k1", Response{Status: 201, Body: []byte(`{"id":"x"}`)}); err != nil {
25			t.Fatal(err)
26		}
27		rec, started, err := s.Begin(ctx, "k1", "fp")
28		if err != nil || started {
29			t.Fatalf("replay Begin: started=%v err=%v", started, err)
30		}
31		if rec.Response.Status != 201 || string(rec.Response.Body) != `{"id":"x"}` {
32			t.Fatalf("replayed %+v", rec.Response)
33		}
34	}
35	
36	func TestBeginErrors(t *testing.T) {
37		ctx := context.Background()
38		tests := []struct {
39			name    string
40			prep    func(s *Memory)
41			fp      string
42			wantErr error
43		}{
44			{"in progress", func(s *Memory) { _, _, _ = s.Begin(ctx, "k", "fp") }, "fp", ErrInProgress},
45			{"different request", func(s *Memory) {
46				_, _, _ = s.Begin(ctx, "k", "fp")
47				_ = s.Complete(ctx, "k", Response{Status: 200})
48			}, "other", ErrKeyReuse},
49		}
50		for _, tt := range tests {
51			t.Run(tt.name, func(t *testing.T) {
52				s, _ := newStore()
53				tt.prep(s)
54				if _, _, err := s.Begin(ctx, "k", tt.fp); !errors.Is(err, tt.wantErr) {
55					t.Fatalf("err = %v, want %v", err, tt.wantErr)
56				}
57			})
58		}
59		s, _ := newStore()
60		if _, _, err := s.Begin(ctx, "", "fp"); !errors.Is(err, ErrEmptyKey) {
61			t.Fatalf("empty key: %v", err)
62		}
63	}
64	
65	func TestReleaseAllowsRetry(t *testing.T) {
66		ctx := context.Background()
67		s, _ := newStore()
68		_, _, _ = s.Begin(ctx, "k", "fp")
69		if err := s.Release(ctx, "k"); err != nil {
70			t.Fatal(err)
71		}
72		if _, started, err := s.Begin(ctx, "k", "fp"); err != nil || !started {
73			t.Fatalf("after release: started=%v err=%v", started, err)
74		}
75		if err := s.Release(ctx, "zzz"); !errors.Is(err, ErrUnknownKey) {
76			t.Fatalf("unknown release: %v", err)
77		}
78	}
79	
80	func TestReplayBodyIsCopied(t *testing.T) {
81		ctx := context.Background()
82		s, _ := newStore()
83		_, _, _ = s.Begin(ctx, "k", "fp")
84		body := []byte("abc")
85		_ = s.Complete(ctx, "k", Response{Status: 200, Body: body})
86		body[0] = 'X'
87		rec, _, _ := s.Begin(ctx, "k", "fp")
88		if string(rec.Response.Body) != "abc" {
89			t.Fatalf("stored body aliased caller slice: %q", rec.Response.Body)
90		}
91	}

 1	// Command server runs the payments API on :8080 with in-memory storage.
 2	package main
 3	
 4	import (
 5		"context"
 6		"log"
 7		"net/http"
 8		"os"
 9		"time"
10	
11		"example.com/gopayments/api"
12		"example.com/gopayments/clock"
13		"example.com/gopayments/idempotency"
14		"example.com/gopayments/payment"
15		"example.com/gopayments/store"
16		"example.com/gopayments/webhook"
17	)
18	
19	func main() {
20		clk := clock.Real{}
21		endpoints := webhook.StaticEndpoints{}
22		if url := os.Getenv("DEMO_WEBHOOK_URL"); url != "" {
23			endpoints["m_demo"] = webhook.Endpoint{URL: url, Secret: os.Getenv("DEMO_WEBHOOK_SECRET")}
24		}
25		hooks := webhook.NewDispatcher(webhook.HTTPSender{Client: &http.Client{Timeout: 10 * time.Second}}, endpoints, clk, webhook.DefaultPolicy())
26		svc := payment.NewService(store.NewMemory(), clk, payment.NewSeqIDs(), hooks, payment.Config{FeeBps: 290})
27		srv := api.NewServer(svc, idempotency.NewMemory(clk, 24*time.Hour), hooks)
28	
29		go func() {
30			for range time.Tick(time.Second) {
31				if err := hooks.Flush(context.Background()); err != nil {
32					log.Printf("webhooks: %v", err)
33				}
34			}
35		}()
36	
37		log.Println("listening on :8080")
38		log.Fatal(http.ListenAndServe(":8080", srv))
39	}

