 14	const maxBodyBytes = 1 << 20
 15	
 16	func (s *Server) createPayment(w http.ResponseWriter, r *http.Request) {
 17		var req createPaymentRequest
 18		if err := decodeJSON(r, &req); err != nil {
 19			writeError(w, err)
 20			return
 21		}
 22		amount, err := money.Parse(req.Amount, req.Currency)
 23		if err != nil {
 24			writeError(w, fmt.Errorf("amount: %w", err))
 25			return
 26		}
 27		in := payment.CreateInput{MerchantID: req.MerchantID, Amount: amount}
 28		s.idempotent(w, r, createFingerprint(in), func() (int, any) {
 29			p, err := s.svc.Create(r.Context(), in)
 30			if err != nil {
 31				return errorResponse(err)
 32			}
 33			return http.StatusCreated, toPaymentResponse(p)
 34		})
 35	}
 36	
 37	func (s *Server) getPayment(w http.ResponseWriter, r *http.Request) {
 38		p, err := s.svc.Get(r.Context(), r.PathValue("id"))
 39		if err != nil {
 40			writeError(w, err)
 41			return
 42		}
 43		writeJSON(w, http.StatusOK, toPaymentResponse(p))
 44	}
 45	
 46	func (s *Server) authorizePayment(w http.ResponseWriter, r *http.Request) {
 47		s.respondPayment(w, func() (payment.Payment, error) { return s.svc.Authorize(r.Context(), r.PathValue("id")) })
 48	}
 49	
 50	func (s *Server) capturePayment(w http.ResponseWriter, r *http.Request) {
 51		s.respondPayment(w, func() (payment.Payment, error) { return s.svc.Capture(r.Context(), r.PathValue("id")) })
 52	}
 53	
 54	func (s *Server) declinePayment(w http.ResponseWriter, r *http.Request) {
 55		var req declineRequest
 56		if r.ContentLength != 0 {
 57			if err := decodeJSON(r, &req); err != nil {
 58				writeError(w, err)
 59				return
 60			}
 61		}
 62		s.respondPayment(w, func() (payment.Payment, error) {
 63			return s.svc.Decline(r.Context(), r.PathValue("id"), req.Reason)
 64		})
 65	}
 66	
 67	func (s *Server) refundPayment(w http.ResponseWriter, r *http.Request) {
 68		id := r.PathValue("id")
 69		var req refundRequest
 70		if err := decodeJSON(r, &req); err != nil {
 71			writeError(w, err)
 72			return
 73		}
 74		p, err := s.svc.Get(r.Context(), id)
 75		if err != nil {
 76			writeError(w, err)
 77			return
 78		}
 79		amount, err := money.Parse(req.Amount, p.Amount.Currency.Code)
 80		if err != nil {
 81			writeError(w, fmt.Errorf("amount: %w", err))
 82			return
 83		}
 84		s.idempotent(w, r, refundFingerprint(id, amount), func() (int, any) {
 85			p, _, err := s.svc.Refund(r.Context(), id, amount)
 86			if err != nil {
 87				return errorResponse(err)
 88			}
 89			return http.StatusCreated, toPaymentResponse(p)
 90		})
 91	}
 92	
 93	func (s *Server) listPayments(w http.ResponseWriter, r *http.Request) {
 94		q := r.URL.Query()
 95		page := payment.Page{Cursor: q.Get("cursor")}
 96		if v := q.Get("limit"); v != "" {
 97			n, err := strconv.Atoi(v)
 98			if err != nil {
 99				writeError(w, fmt.Errorf("%w: limit %q is not a number", payment.ErrInvalidInput, v))
100				return
101			}
102			page.Limit = n
103		}
104		ps, next, err := s.svc.List(r.Context(), r.PathValue("merchantID"), page)
105		if err != nil {
106			writeError(w, err)
107			return
108		}
109		out := listResponse{Data: make([]paymentResponse, 0, len(ps)), NextCursor: next}
110		for _, p := range ps {
111			out.Data = append(out.Data, toPaymentResponse(p))
112		}
113		writeJSON(w, http.StatusOK, out)
114	}
115	
116	func (s *Server) listDeadLetters(w http.ResponseWriter, _ *http.Request) {
117		dead := s.hooks.DeadLetters()
118		out := make([]deadLetterResponse, 0, len(dead))
119		for _, d := range dead {
120			out = append(out, toDeadLetterResponse(d))
121		}
122		writeJSON(w, http.StatusOK, map[string]any{"data": out})
123	}
124	
125	func (s *Server) respondPayment(w http.ResponseWriter, op func() (payment.Payment, error)) {
126		p, err := op()
127		if err != nil {
128			writeError(w, err)
129			return
130		}
131		writeJSON(w, http.StatusOK, toPaymentResponse(p))
132	}
133	
134	func decodeJSON(r *http.Request, dst any) error {
135		dec := json.NewDecoder(io.LimitReader(r.Body, maxBodyBytes))
136		dec.DisallowUnknownFields()
137		if err := dec.Decode(dst); err != nil {
138			return fmt.Errorf("%w: malformed JSON body: %v", payment.ErrInvalidInput, err)
139		}
140		return nil
141	}
142	
143	func writeJSON(w http.ResponseWriter, status int, body any) {
144		w.Header().Set("Content-Type", "application/json")
145		w.WriteHeader(status)
146		_ = json.NewEncoder(w).Encode(body)
147	}

