func TestReplayBodyIsCopied(t *testing.T) {
	ctx := context.Background()
	s, _ := newStore()
	_, _, _ = s.Begin(ctx, "k", "fp")
	body := []byte("abc")
	_ = s.Complete(ctx, "k", Response{Status: 200, Body: body})
	body[0] = 'X'
	rec, _, _ := s.Begin(ctx, "k", "fp")
	if string(rec.Response.Body) != "abc" {
		t.Fatalf("stored body aliased caller slice: %q", rec.Response.Body)
	}
}

func TestExpiryBoundaryAndReplayDoesNotSlideTTL(t *testing.T) {
	ctx := context.Background()
	s, clk := newStore()

	_, started, err := s.Begin(ctx, "k", "fp1")
	if err != nil || !started {
		t.Fatalf("initial Begin: started=%v err=%v", started, err)
	}
	if err := s.Complete(ctx, "k", Response{Status: 201, Body: []byte("old")}); err != nil {
		t.Fatal(err)
	}

	// Just before 24h from first use: replay, key reuse, and in-progress still apply,
	// and a replay does not extend the TTL. Also triggers a purge right before expiry
	// so at exact expiry the purge interval has not elapsed yet.
	clk.Advance(24*time.Hour - time.Nanosecond)
	rec, started, err := s.Begin(ctx, "k", "fp1")
	if err != nil || started || string(rec.Response.Body) != "old" {
		t.Fatalf("before expiry replay: started=%v err=%v body=%q", started, err, rec.Response.Body)
	}
	if _, _, err := s.Begin(ctx, "k", "fp2"); !errors.Is(err, ErrKeyReuse) {
		t.Fatalf("before expiry reuse: err=%v, want ErrKeyReuse", err)
	}

	// Exact expiry (now == first use + TTL): starts a new request even though
	// purgeLocked is throttled by DefaultPurgeInterval.
	clk.Advance(time.Nanosecond)
	rec, started, err = s.Begin(ctx, "k", "fp1")
	if err != nil || !started || len(rec.Response.Body) != 0 {
		t.Fatalf("at exact expiry: started=%v err=%v rec=%+v", started, err, rec)
	}
	if err := s.Complete(ctx, "k", Response{Status: 201, Body: []byte("new")}); err != nil {
		t.Fatal(err)
	}

	// Replay after completing the second lifecycle returns the new response.
	clk.Advance(time.Hour)
	rec, started, err = s.Begin(ctx, "k", "fp1")
	if err != nil || started || string(rec.Response.Body) != "new" {
		t.Fatalf("replay new record: started=%v err=%v body=%q", started, err, rec.Response.Body)
	}
	if _, _, err := s.Begin(ctx, "k", "fp2"); !errors.Is(err, ErrKeyReuse) {
		t.Fatalf("reuse before second expiry: err=%v, want ErrKeyReuse", err)
	}
}

func TestExpiredKeyAllowsDifferentFingerprintAndInProgressReset(t *testing.T) {
	ctx := context.Background()

	t.Run("different fingerprint after expiry", func(t *testing.T) {
		s, clk := newStore()
		_, _, _ = s.Begin(ctx, "k", "fp1")
		_ = s.Complete(ctx, "k", Response{Status: 201, Body: []byte("v1")})

		clk.Advance(24 * time.Hour)
		if _, started, err := s.Begin(ctx, "k", "fp2"); err != nil || !started {
			t.Fatalf("after expiry with new fingerprint: started=%v err=%v", started, err)
		}
	})

	t.Run("in-progress key expires", func(t *testing.T) {
		s, clk := newStore()
		_, _, _ = s.Begin(ctx, "k", "fp1")

