func TestIdempotentCreateReplays(t *testing.T) {
	a := newTestAPI(t)
	body := `{"merchant_id":"m_1","amount":"10.00","currency":"USD"}`
	first := a.do("POST", "/payments", body, IdempotencyKeyHeader, "abc")
	second := a.do("POST", "/payments", body, IdempotencyKeyHeader, "abc")
	if first.Code != http.StatusCreated || second.Code != http.StatusCreated {
		t.Fatalf("codes %d %d", first.Code, second.Code)
	}
	if second.Header().Get(ReplayedHeader) != "true" || first.Body.String() != second.Body.String() {
		t.Fatalf("not replayed: %s vs %s", first.Body, second.Body)
	}
	other := a.do("POST", "/payments", `{"merchant_id":"m_1","amount":"11.00","currency":"USD"}`, IdempotencyKeyHeader, "abc")
	if other.Code != http.StatusUnprocessableEntity {
		t.Fatalf("reuse with other body: %d %s", other.Code, other.Body)
	}
}

func TestIdempotentCreateExpiresAfterTTL(t *testing.T) {
	a := newTestAPI(t)
	body := `{"merchant_id":"m_1","amount":"10.00","currency":"USD"}`

	first := a.do("POST", "/payments", body, IdempotencyKeyHeader, "daily-1")
	if first.Code != http.StatusCreated {
		t.Fatalf("first status %d: %s", first.Code, first.Body)
	}
	p1 := decode[paymentResponse](t, first)

	// 40h later (after the 24h TTL): same key and same body creates a new payment.
	a.clk.Advance(40 * time.Hour)
	after := a.do("POST", "/payments", body, IdempotencyKeyHeader, "daily-1")
	if after.Code != http.StatusCreated {
		t.Fatalf("after 40h status %d: %s", after.Code, after.Body)
	}
	if after.Header().Get(ReplayedHeader) != "" {
		t.Fatalf("unexpected replay header after TTL expiry")
	}
	p2 := decode[paymentResponse](t, after)
	if p2.ID == p1.ID {
		t.Fatalf("expected new payment ID after TTL, got same ID %s", p2.ID)
	}

	// Exactly 24h after the second request: reusing with a different body also creates a new payment.
	a.clk.Advance(24 * time.Hour)
	diff := a.do("POST", "/payments", `{"merchant_id":"m_1","amount":"25.00","currency":"USD"}`, IdempotencyKeyHeader, "daily-1")
	if diff.Code != http.StatusCreated || diff.Header().Get(ReplayedHeader) != "" {
		t.Fatalf("after 24h different body: %d %s", diff.Code, diff.Body)
	}
	p3 := decode[paymentResponse](t, diff)
	if p3.ID == p2.ID || p3.Amount != "25.00" {
		t.Fatalf("unexpected third payment %+v", p3)
	}
}

